func (q *Queries) ListAuditObjectsInRange(ctx context.Context, arg ListAuditObjectsInRangeParams) ([]AuditObject, error) {
	rows, err := q.db.Query(ctx, listAuditObjectsInRange, arg.OrganizationID, arg.FromDay, arg.ToDay)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AuditObject{}
	for rows.Next() {
		var i AuditObject
		if err := rows.Scan(
			&i.ObjectKey,
			&i.OrganizationID,
			&i.Day,
			&i.EventCount,
			&i.Sha256,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

